//#region src/fps/fpsPersonality.ts
const initialFpsPsychology = () => ({
	confidence: 50,
	composure: 70,
	frustration: 10,
	winStreak: 0,
	lossStreak: 0,
	lastRound: 0
});
function getFpsPreferences(card, mood = initialFpsPsychology()) {
	const p = fpsBehaviorPreferences(card.fpsIdentity?.personality ?? generateFpsPersonality(card.id)), momentum = (mood.confidence - 50) / 100 * p.pressureSensitivity;
	return {
		aggression: (p.initiative - .5) * 2 + momentum,
		coordination: (p.coordination - .5) * 2,
		patience: (p.deliberation + .5 - p.initiative) / 2,
		utility: p.coordination - .5,
		conservation: .5 - p.initiative,
		leadership: 0
	};
}
function updateFpsPsychology(player, won, roundNumber, _teammates) {
	const mood = player.psychology ?? initialFpsPsychology();
	if (roundNumber <= mood.lastRound) return;
	const sensitivity = .3 + fpsBehaviorPreferences(player.card.fpsIdentity?.personality ?? generateFpsPersonality(player.playerId)).pressureSensitivity;
	const bound = (n) => Math.max(0, Math.min(100, n));
	player.psychology = {
		confidence: bound(mood.confidence + (won ? 5 : -5) * sensitivity),
		composure: 70,
		frustration: bound(mood.frustration + (won ? -8 : 8 * sensitivity) - 3),
		winStreak: won ? Math.min(5, mood.winStreak + 1) : 0,
		lossStreak: won ? 0 : Math.min(5, mood.lossStreak + 1),
		lastRound: roundNumber
	};
}
function updateContextualFpsPsychology(player, won, roundNumber, _dna, _trust) {
	updateFpsPsychology(player, won, roundNumber, []);
}
function fpsRoleScore(player, role) {
	const s = player.card.stats;
	return role === "caller" ? s.shotcalling : role === "entry" ? s.entry : role === "support" ? s.utility : role === "sniper" ? s.sniping : role === "trade" ? s.rifling : s.positioning;
}
function rankFpsPlayers(players, role) {
	return [...players].sort((a, b) => fpsRoleScore(b, role) - fpsRoleScore(a, role) || a.playerId.localeCompare(b.playerId));
}
/** Allocation assigns positions once. This helper only updates the round view of those assignments. */
function assignFpsTeamRoles(players, _contextual = false) {
	const t = [
		"caller",
		"entry",
		"support",
		"lurker",
		"trade"
	], ct = [
		"caller",
		"trade",
		"anchor",
		"anchor",
		"trade"
	];
	players.forEach((p, i) => {
		const position = p.card.fpsIdentity?.assignments?.[p.side === "attackers" ? "t" : "ct"];
		const role = position ? fpsExecutionRole(position) : (p.side === "attackers" ? t : ct)[i], mood = p.psychology ?? initialFpsPsychology();
		p.tactics = {
			role,
			position,
			isCaller: position ? position.endsWith("IGL") : i === 0,
			traits: [],
			mood: { ...mood },
			preferences: getFpsPreferences(p.card, mood),
			reason: "Locked lineup responsibility"
		};
	});
}
function shouldSaveFpsRetake(defenders, attackers) {
	const living = defenders.filter((p) => p.isAlive), enemies = attackers.filter((p) => p.isAlive);
	return living.length > 0 && living.length <= 2 && enemies.length - living.length >= 2 && living.some((p) => p.loadout.primaryWeapon) && living.reduce((sum, p) => sum + getFpsPreferences(p.card, p.psychology).conservation, 0) / living.length >= .25;
}

