		const origin = axis === 0 ? from.x : from.z, delta = axis === 0 ? to.x - from.x : to.z - from.z;
		const min = (axis === 0 ? wall.minX : wall.minZ) - radius, max = (axis === 0 ? wall.maxX : wall.maxZ) + radius;
