				for (const b of this._sharedData.dynamicUniformBlocks) b.updateUniformsAndSamples(this._vertexCompilationState, this, defines, uniformBuffers);
				const mergedUniforms = this._vertexCompilationState.uniforms;
				for (const u of this._fragmentCompilationState.uniforms) if (mergedUniforms.indexOf(u) === -1) mergedUniforms.push(u);
