function resolveSpillwayAsset(id) {
	const exact = EXACT_ASSETS[id];
	if (exact) return exact;
	if (id.includes("rail")) return {
		purpose: "Yellow municipal safety railing",
		surface: "metal",
		acoustic: "metal",
		color: METAL_RAIL
	};
	if (id.includes("pump") || id.includes("pipe") || id.includes("valve")) return {
		purpose: "Blue flood control machinery",
		surface: "metal",
		acoustic: "metal",
		color: PUMP_BLUE
	};
	if (id.includes("planter")) return {
		purpose: "Landscaped masonry park planter",
		surface: "stone",
		acoustic: "stone",
		color: PLANTER
	};
	if (id.includes("crate") || id.includes("pallet") || id.includes("pergola") || id.includes("bench") || id.includes("picnic")) return {
		purpose: "Timber street furniture or crate",
		surface: "timber",
		acoustic: "wood",
		color: TIMBER
	};
	if (id.includes("tree")) return {
		purpose: "Urban riverside park tree trunk",
		surface: "timber",
		acoustic: "wood",
		color: "#614e3a"
	};
	if (id.includes("tunnel") || id.includes("culvert") || id.includes("ceiling") || id.includes("squeaky")) return {
		purpose: "Vaulted concrete drainage culvert",
		surface: "concrete",
		acoustic: "concrete",
		color: TUNNEL_VAULT
	};
	if (id.includes("parkhouse")) return {
		purpose: "Parkhouse restroom pavilion wall",
		surface: "clay",
		acoustic: "brick",
		color: "#bfa284"
	};
	if (id.includes("bank")) return {
		purpose: "Municipal Hydrology Bank masonry",
		surface: "concrete",
		acoustic: "concrete",
		color: "#9ca1a3"
	};
	if (id.includes("jail")) return {
		purpose: "Maintenance cage barrier wall",
		surface: "concrete",
		acoustic: "concrete",
		color: "#7f868a"
	};
	if (id.includes("bridge")) return {
		purpose: "Canal steel truss footbridge",
		surface: "metal",
		acoustic: "metal",
		color: "#5b666b"
	};
	if (id.includes("kiosk") || id.includes("promenade")) return {
		purpose: "Park promenade brick pavilion",
		surface: "clay",
		acoustic: "brick",
		color: BRICK_PATH
	};
	if (id.includes("retaining") || id.includes("cliff") || id.includes("spine") || id.includes("pier")) return {
		purpose: "Weathered concrete retaining wall",
		surface: "concrete",
		acoustic: "concrete",
		color: RETAINING
	};
	if (id.includes("roof") || id.includes("overpass")) return {
		purpose: "Overpass concrete roof structure",
		surface: "concrete",
		acoustic: "concrete",
		color: CONCRETE_DARK
	};
	if (/-patch-\d+/.test(id)) return {
		purpose: "Flood-control terrain and retaining patch",
		surface: "concrete",
		acoustic: "concrete",
		color: CONCRETE_WALL
	};
	return {
		purpose: "Municipal flood control masonry wall",
		surface: "concrete",
		acoustic: "concrete",
		color: CONCRETE_WALL
	};
}

