		if (ctx.phase === "retake" || ctx.phase === "post-plant" && !t) return intent(ctx, "Blind post-plant positions for the retake", "RETAKE_SUPPORT", "ENEMY_BLINDING", ctx.teammateEngaging && "ENTRY_SUPPORT");
